const hash=async value=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',typeof value==='string'?new TextEncoder().encode(value):value))).map(x=>x.toString(16).padStart(2,'0')).join('');
const parse=row=>row?{...JSON.parse(row.data),id:row.id,wg:row.wg,version:row.version,status:row.status}:null;
async function init(env){need(env.DB,'Dauerhafte Datenbank ist nicht gebunden.',503);if(!ready.has(env.DB))ready.set(env.DB,env.DB.batch(SCHEMA.map(sql=>env.DB.prepare(sql))).catch(e=>{ready.delete(env.DB);throw e;}));await ready.get(env.DB);}
async function settings(env){const r=await env.DB.prepare('SELECT key,value FROM settings').all();return Object.fromEntries(r.results.map(v=>[v.key,JSON.parse(v.value)]));}
async function setting(env,key,value){await env.DB.prepare('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').bind(key,JSON.stringify(value)).run();}
async function encryptionKey(env){need(env.CONFIG_KEY,'Geschützte Konfiguration fehlt.',503);return crypto.subtle.importKey('raw',Uint8Array.from(atob(env.CONFIG_KEY),c=>c.charCodeAt(0)),{name:'AES-GCM'},false,['encrypt','decrypt']);}
async function protect(env,value){const iv=crypto.getRandomValues(new Uint8Array(12));const c=await crypto.subtle.encrypt({name:'AES-GCM',iv},await encryptionKey(env),new TextEncoder().encode(value));return btoa(String.fromCharCode(...iv,...new Uint8Array(c)));}
async function unprotect(env,value){if(!value)return '';const bytes=Uint8Array.from(atob(value),c=>c.charCodeAt(0));return new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:bytes.slice(0,12)},await encryptionKey(env),bytes.slice(12)));}
async function configuration(env,secretKeys=['hubKey','resendKey','qontoKey','calendarToken']){const s=await settings(env);const c={...s};for(const k of secretKeys){try{c[k]=await unprotect(env,s[k]);}catch{throw new AppError(({hubKey:'Hub',resendKey:'Resend',qontoKey:'Qonto',calendarToken:'Kalender'})[k]+'-Zugang kann nicht entschlüsselt werden. Bitte diesen Schlüssel erneut geschützt speichern.',503);}}return c;}
async function owner(request,env){const email=request.headers.get('oai-authenticated-user-email')?.trim().toLowerCase();need(email&&env.OWNER_EMAIL_SHA256&&(await hash(email))===env.OWNER_EMAIL_SHA256,'Nur der Betreiber darf das Panel öffnen.',403);return 'owner';}
async function body(request){need(Number(request.headers.get('content-length')??0)<1500000,'Anfrage zu groß.',413);const raw=await request.text();need(raw.length<1500000,'Anfrage zu groß.',413);try{return JSON.parse(raw);}catch{throw new AppError('Ungültige Eingabe.');}}
function csrf(request){need(request.headers.get('origin')===new URL(request.url).origin,'Ungültiger Ursprung.',403);need(request.headers.get('content-type')?.startsWith('application/json'),'JSON-Eingabe erforderlich.',415);}
