function integrationStatus(s,env){return {website:s.hubVerified?'Lesender Zugriff geprüft':s.websiteError??'Schlüssel fehlt oder wurde bei der Prüfung abgewiesen',email:s.emailVerified?(s.sendApproved?'Domain geprüft; Versand freigegeben':'Domain geprüft; Versand noch freizugeben'):'Versandanbieter nicht geprüft',calendar:s.calendarVerified?(env.STANDALONE_AUTH==='true'&&s.calendarOAuth?'Google-OAuth mit Token-Erneuerung verbunden; Terminabgleich verfügbar':'Lesender Zugriff geprüft; Kalenderexport verfügbar'):'Privater Kalenderexport verfügbar; automatische Verbindung offen',qonto:s.qontoVerified?(env.STANDALONE_AUTH==='true'?(s.qontoIban?'Qonto geprüft; Rechnung und Quittung nach Rückgabe verfügbar':'Qonto geprüft; Zahlungskonto für Rechnungen auswählen'):'Lesender Zugriff geprüft; Rechnungsablauf nur im IONOS-Panel'):s.qontoError??'Qonto nicht verbunden',numbers:s.numberAudit?'Nummernstand abgeglichen':'WG-Nummernabgleich erforderlich',customer:env.CUSTOMER_ACCESS_APPROVED==='true'?(env.STANDALONE_AUTH==='true'?'Persönliche E-Mail-Anmeldung; ausschließlich eigenes Angebot':'Annahme geschützt vorbereitet; Kundenkonto gezielt freigeben'):'Kundenannahme vorbereitet; externe Freigabe fehlt',background:(env.STANDALONE_AUTH==='true'?(s.lastScheduledError?'IONOS-Hintergrundlauf angehalten: '+s.lastScheduledError+'. ':s.lastScheduledAt?'IONOS-Hintergrundlauf; letzter geplanter Erfolg '+berlin(s.lastScheduledAt)+'. ':'IONOS-Lauf vorbereitet; geplanter Erfolg noch zu prüfen. '):env.BACKGROUND_STATE==='paused'?'Cloudlauf pausiert: Betreiberanmeldung in der Cloud fehlt. Jetzt prüfen bleibt verfügbar. ':env.BACKGROUND_CADENCE==='hourly'?'Stündlicher Cloudplan vorhanden; erfolgreicher automatischer Lauf noch nachzuweisen. ':'Unabhängiger Cloudlauf noch nicht geprüft. ')+(s.lastBackgroundAt?'Letzte erfolgreiche Fälligkeitsprüfung: '+berlin(s.lastBackgroundAt):'Noch keine erfolgreiche Fälligkeitsprüfung')};}
