async function background(env){await init(env);let config=await settings(env);const at=new Date().toISOString();let deliveryError=null,remaining=5;if(config.backgroundApproved&&config.emailVerified&&config.sendApproved){try{config=await configuration(env,['resendKey']);}catch(e){deliveryError=e.message;}}// Completed orders are only read while a consented review mail can still become due.
  const rows=await env.DB.prepare("SELECT * FROM orders WHERE synthetic=0 AND (status IN ('Angebot offen','Termin verbindlich') OR (status IN ('Erledigt','Bezahlt') AND json_extract(data,'$.source.reviewConsent')=1 AND NOT EXISTS(SELECT 1 FROM jobs j WHERE j.order_id=orders.id AND j.kind='review' AND j.state<>'failed')))").all();for(const row of rows.results){const o=parse(row);if(isTrashedOrder(o))continue;if(o.status==='Angebot offen'&&Date.parse(o.offer.expiresAt)<=Date.now()){try{await saveOrder(env,transition(o,'expire',{}),o.version,'Angebot abgelaufen','background');}catch(e){if(!(e instanceof AppError&&e.status===409))throw e;}continue;}
    // Scheduling and actual customer delivery deliberately require independent verified activation.
    if(recordOperationIssue(o,'send')||deliveryError||remaining<=0||!config.backgroundApproved||!config.emailVerified||!config.sendApproved)continue;
    for(const kind of dueJobs(o)){if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(o.source.email??'')){deliveryError='Kunden-E-Mail fehlt oder ist ungültig.';continue;}if(kind==='review'&&!/^https:\/\//.test(config.reviewUrl??''))continue;const job=await claimJob(env,o,kind);if(!job)continue;const current=await getOrder(env,o.id);if(recordOperationIssue(current,'send')||!dueJobs(current).includes(kind)){await env.DB.prepare("UPDATE jobs SET state='cancelled',updated_at=? WHERE id=?").bind(at,job).run();continue;}
      remaining--;try{const message=kind==='review'?'Danke für Ihr Vertrauen. Wenn Sie möchten, bewerten Sie White Gloss: '+config.reviewUrl:'Ihr verbindlicher Termin bei White Gloss: '+berlin(current.appointment.start)+'. '+current.appointment.delivery;assertCurrentRecordOperation(env,current,'send',current.version);const r=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:'Bearer '+config.resendKey,'Content-Type':'application/json','Idempotency-Key':'wg-'+current.id+'-'+kind},body:JSON.stringify({from:config.sender,to:[current.source.email],subject:kind==='review'?'Ihre Bewertung für White Gloss':'Ihr Termin bei White Gloss',text:message}),signal:AbortSignal.timeout(20000),redirect:'manual'});const d=await r.json();need(r.ok&&d.id,'Providerergebnis nicht eindeutig.');await env.DB.prepare("UPDATE jobs SET state='sent',provider_id=?,updated_at=? WHERE id=?").bind(d.id,new Date().toISOString(),job).run();}
      catch{deliveryError='Versandergebnis ungeklärt. Providerabgleich erforderlich; kein Neuversuch.';await env.DB.prepare("UPDATE jobs SET state='unknown',detail='Unklares Ergebnis. Kein automatischer Neuversuch. Providerabgleich erforderlich.',updated_at=? WHERE id=?").bind(new Date().toISOString(),job).run();}
    }
  }await env.DB.prepare("UPDATE jobs SET state='unknown',detail='Voriger Lauf ohne eindeutiges Ergebnis beendet. Providerabgleich erforderlich; kein Neuversuch.',updated_at=? WHERE state='pending' AND created_at<?").bind(at,new Date(Date.now()-3600000).toISOString()).run();await setting(env,'lastBackgroundAt',new Date().toISOString());await setting(env,'lastBackgroundError',deliveryError);return {ok:true,at,deliveryError};}
